@@ -0,0 +1,19 @@
+package com.readtogether.reading;
+
+import lombok.RequiredArgsConstructor;
+import org.springframework.web.bind.annotation.*;
+
+@RestController
+@RequiredArgsConstructor
+public class ReadingLogController {
+    private final ReadingLogService service;
+
+    @PostMapping("/api/books/{bookId}/reading-logs")
+    public CreatedResponse create(@PathVariable Long bookId, @RequestBody ReadingLogRequest request) {
+        ReadingLog saved = service.recordProgress(bookId, request.memberId(), request.currentPage(), request.memo());
+        return new CreatedResponse(saved.getId());
+    }
+
+    public record ReadingLogRequest(Long memberId, int currentPage, String memo) {}
+    public record CreatedResponse(Long logId) {}
+}

diff --git a/frontend/src/features/reading/ReadingProgressPanel.tsx b/frontend/src/features/reading/ReadingProgressPanel.tsx
--- a/frontend/src/features/reading/ReadingProgressPanel.tsx
+++ b/frontend/src/features/reading/ReadingProgressPanel.tsx
@@ -1,2 +1,26 @@
-export function FeaturePanel() { return null; }
-// 화면 구현 예정
+import { useState } from 'react';
+import { api } from '../../lib/api';
+
+type Props = { bookId: number; memberId: number; reload: () => Promise<void> };
+
+export function ReadingProgressPanel({ bookId, memberId, reload }: Props) {
+  const [currentPage, setCurrentPage] = useState(0);
+  const [memo, setMemo] = useState('');
+  const [error, setError] = useState('');
+  async function submit() {
+    setError('');
+    try {
+      await api.post(`/api/books/${bookId}/reading-logs`, { memberId, currentPage, memo });
+      await reload();
+    } catch {
+      setError('요청을 처리하지 못했습니다. 잠시 후 다시 시도해주세요.');
+    }
+  }
+  return <section>
+    <h2>독서 진행 기록</h2>
+    <label>읽은 페이지<input type="number" value={currentPage} onChange={e => setCurrentPage(Number(e.target.value))} /></label>
+    <label>독서 메모<input value={memo} onChange={e => setMemo(e.target.value)} /></label>
+    {error && <p role="alert">{error}</p>}
+    <button onClick={submit}>저장하기</button>
+  </section>;
+}

