+import static org.assertj.core.api.Assertions.assertThat;
+import static org.mockito.Mockito.*;
+
+class ReadingLogServiceTest {
+    @Test
+    void returnsCreatedRecordForValidRequest() {
+        var books = mock(BookRepository.class);
+        var logs = mock(ReadingLogRepository.class);
+        var resource = mock(Book.class);
+        when(books.findById(1L)).thenReturn(Optional.of(resource));
+        when(resource.getId()).thenReturn(1L);
+        when(logs.save(any(ReadingLog.class))).thenAnswer(invocation -> invocation.getArgument(0));
+        var service = new ReadingLogService(books, logs);
+        var saved = service.recordProgress(1L, 7L, 80, "첫 장을 읽었습니다.");
+        assertThat(saved).isNotNull();
+        verify(logs).save(any(ReadingLog.class));
+    }
+}
